// Draws the strip from flock.js's facts. Art comes from `art/`, generated by art/build.mjs.
import { div, image } from "gpui-kit";
import { ART, STRIP_ROWS, TILE_PX, bodyAt, cloudsAt, lampOn, phaseAt, propsOn, skyFor } from "./world.js";
import { DOG_H, DOG_W, SHEEP_H, SHEEP_W, WOLF_H, WOLF_W } from "./flock.js";
import { count } from "./game.js";

const LANE_FEET = [41, 44, 47];
export const PIXEL_FONT = "Woolhill Pixel";

export const art = (name, kind = "png") => `mods/woolhill/art/${name}.${kind}`;

const picture = (name, kind) => image(art(name, kind));
const placed = (el, x, top, w, h) => el.absolute().left(x).top(top).w(w).h(h);

function sky(palette, ground, width) {
  const bands = palette.bands, each = Math.ceil(ground / bands.length);
  return bands.map((colour, i) => div().absolute().left(0).top(i * each).w(width).h(each + 1).bg(colour));
}

function heavens(model, top, width, phase) {
  const { hour, minute, look } = model, list = [];
  if (phase === "night") {
    for (let n = 0; n * 240 < width; n++) list.push(placed(picture("stars"), n * 240, top, 240, 36));
  }
  const body = bodyAt(hour, minute);
  list.push(placed(picture(body.art), Math.round(body.across * (width - 36)), top + Math.round((1 - body.height) * 56) + 3, 36, 36));
  for (const cloud of cloudsAt(hour, minute, width)) {
    list.push(placed(picture(phase === "night" || look === "dark" ? `${cloud.art}-dim` : cloud.art), cloud.x, top + cloud.top, cloud.w, cloud.h));
  }
  return list;
}

function hills(model, top, width) {
  const list = [];
  for (let n = 0; n * TILE_PX < width; n++) list.push(placed(picture(`hill-${model.look}-${model.state.season}`), n * TILE_PX, top, TILE_PX, STRIP_ROWS * ART));
  return list;
}

const feetTop = (lane, top, height) => top + LANE_FEET[lane] * ART - height;

function sheepEl(sheep, model, top) {
  const breed = model.breedOf(sheep.address);
  const gif = sheep.mode === "walk" || sheep.mode === "graze";
  const y = feetTop(sheep.lane, top, SHEEP_H) - (sheep.hopping ? 20 : 0);
  return div().id(`sheep-${sheep.address}`).absolute().left(sheep.x).top(y).w(SHEEP_W).h(SHEEP_H)
    .transition("left", { duration: Math.max(1, sheep.moveMs), easing: "linear" })
    .transition("top", { duration: 170, easing: sheep.hopping ? "ease-out" : "ease-in" })
    .tooltip(model.label(sheep.address))
    .on_click(() => model.jump(sheep.address))
    .child(picture(`sheep-${breed}-${sheep.mode}-${sheep.facing}`, gif ? "gif" : "png").size_full());
}

function wolfEl(wolf, model, top) {
  const gif = wolf.mode !== "stand";
  return div().id(`wolf-${wolf.address}`).absolute().left(wolf.x).top(feetTop(wolf.lane, top, WOLF_H)).w(WOLF_W).h(WOLF_H)
    .transition("left", { duration: Math.max(1, wolf.moveMs), easing: wolf.mode === "run" ? "ease-in" : "linear" })
    .tooltip(model.label(wolf.address))
    .on_click(() => model.jump(wolf.address))
    .child(picture(`wolf-${wolf.mode}-${wolf.facing}`, gif ? "gif" : "png").size_full());
}

function dogEl(dog, top) {
  const gif = dog.mode === "trot";
  return div().id("dog").absolute().left(dog.x).top(feetTop(dog.lane, top, DOG_H)).w(DOG_W).h(DOG_H)
    .transition("left", { duration: Math.max(1, dog.moveMs), easing: "linear" })
    .child(picture(`dog-${dog.mode}-${dog.facing}`, gif ? "gif" : "png").size_full());
}

function tuftEl(tuft, top) {
  return div().id(`tuft-${tuft.id}`).absolute().left(tuft.x).top(feetTop(tuft.lane, top, 21)).w(27).h(21)
    .child(picture("tuft").size_full())
    .when(tuft.labelled, (el) => el.child(div().absolute().left(-6).top(-18).w(48).font_family(PIXEL_FONT).text_size(16).text_color("#fff8ec").child(`+${tuft.wool}`)));
}

// Back lanes first, so a nearer sheep stands in front.
function actors(model, top) {
  const { flock } = model, list = [];
  for (const sheep of flock.sheep.values()) list.push({ lane: sheep.lane, x: sheep.x, el: sheepEl(sheep, model, top) });
  for (const wolf of flock.wolves.values()) list.push({ lane: wolf.lane, x: wolf.x, el: wolfEl(wolf, model, top) });
  if (flock.dog) list.push({ lane: flock.dog.lane, x: flock.dog.x, el: dogEl(flock.dog, top) });
  for (const tuft of flock.tufts) list.push({ lane: tuft.lane, x: tuft.x, el: tuftEl(tuft, top) });
  return list.sort((a, b) => a.lane - b.lane || a.x - b.x).map((a) => a.el);
}

function sign(model) {
  return div().id("sign").absolute().right(10).top(8).px(10).py(5).rounded(4).bg("#33242fd8").border_1().border_color("#00000040")
    .font_family(PIXEL_FONT).text_size(16).text_color("#fff0a8")
    .hover((s) => s.bg("#4a3546e8"))
    .on_click(() => model.openShop())
    .child(count(model.state.wool));
}

// The hill as bought, with one sheep of each breed, for the Flock page.
export function hillPreview(state, look, breeds, width) {
  const palette = skyFor(look, "day"), top = 0, shown = { look, state };
  const things = propsOn(state, width).map((p) => placed(picture(p.art), p.x, top + p.top, p.w, p.h));
  const gap = width / (breeds.length + 1);
  const flock = breeds.map((breed, i) => placed(picture(`sheep-${breed}-stand-${i % 2 ? "l" : "r"}`), Math.round(gap * (i + 1) - SHEEP_W / 2), feetTop(i % 2 ? 1 : 2, top, SHEEP_H), SHEEP_W, SHEEP_H));
  return div().relative().w(width).h(STRIP_ROWS * ART).flex_none().overflow_hidden().rounded(8).bg(palette.bands[0])
    .children(sky(palette, 22 * ART, width))
    .children(hills(shown, top, width))
    .children(things)
    .children(flock);
}

export function stripView(model, onSize) {
  const { width, height } = model, phase = phaseAt(model.hour), palette = skyFor(model.look, phase);
  // Anchored to the bottom: a taller block shows more sky and a shorter one crops it. Under a unit off is the zoom's rounding.
  const spare = height - STRIP_ROWS * ART, top = Math.abs(spare) < 1 ? 0 : Math.round(spare), ground = top + 22 * ART;
  const things = propsOn(model.state, width).map((p) => placed(picture(p.art), p.x, top + p.top, p.w, p.h));
  const lamp = lampOn(model.state, width, phase);
  return div().id("root").relative().size_full().overflow_hidden().bg(palette.bands[0])
    .on_size_change(onSize)
    .children(sky(palette, ground, width))
    .children(heavens(model, Math.max(0, top - 4), width, phase))
    .children(hills(model, top, width))
    .children(things)
    .children(actors(model, top))
    .when(Boolean(palette.shade), (el) => el.child(div().absolute().left(0).top(0).w(width).h(height).bg(palette.shade)))
    .when(Boolean(lamp), (el) => el.child(placed(div().bg("#fff0a8"), lamp.x, top + lamp.top, lamp.w, lamp.h)).child(placed(div().bg("#f6cf5c30"), lamp.x - 9, top + lamp.top - 9, lamp.w + 18, lamp.h + 18)))
    .child(sign(model));
}
